    tx.execute("INSERT INTO ledger (user, amount, key, created_at) VALUES (?1, ?2, ?3, ?4)", rusqlite::params![user, delta.to_string(), key, std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map(|d| d.as_secs() as i64).unwrap_or(0)])?;
